update public.places set address = '강원특별자치도 속초시 일원', latitude = 38.161979, longitude = 128.499113, summary = '비룡폭포 위에서 토왕성폭포를 바라보는 전망대', tags = '{}', description = null, hours_summary = null, closed_summary = null, price_summary = null, phone = null, parking_summary = null, cautions = null, operation_status = 'open', status_note = null, verified_on = null
where slug = 'towangseong-falls-observatory' and activity_category = 'nature' and description is not distinct from '상·중·하 3단을 합쳐 약 320m에 이르는 토왕성폭포를 멀리서 바라보는 전망대로, 비룡폭포 탐방로를 약 400m 늘려 만들었습니다. 소공원에서 육담폭포·비룡폭포를 지나 약 2.8km, 편도 1시간 30분 안팎이 걸리며, 비룡폭포부터 전망대까지는 계단이 많아 가장 힘든 구간입니다. 겨울에는 폭포가 얼어 큰 빙폭이 되고, 날씨가 흐리면 폭포가 잘 보이지 않을 수 있습니다.';
